# Read the exact cell values again from the cached original workbook, preserving all five years separately.
import openpyxl
w=openpyxl.load_workbook(ROOT/'.generated/population-184/stat-environment-2025.xlsx',read_only=True,data_only=True)
for sheet,row,sid,label in [('Т. 4.16-4.19',49,'argali','архар'),('Т. 4.16-4.19',53,'cervus-elaphus-asiaticus','марал'),('Т. 4.19 прод-4.21',9,'ursus-arctos','медведь'),('Т. 4.19 прод-4.21',16,'eurasian-lynx','рысь туркестанская'),('Т. 4.19 прод-4.21',25,'golden-eagle','беркут'),('Т. 4.19 прод-4.21',21,'lyrurus-tetrix','тетерев')]:
    s=w[sheet]
    values=list(s.iter_rows(min_row=row,max_row=row,values_only=True))[0]
    occupied=[(idx+1,v) for idx,v in enumerate(values) if v is not None]
    assert label in str(occupied[0][1]).lower()
    # Nonempty columns contain label then five annual values; '-' is missing/not reported, not 0.
    assert len(occupied)==6
    for year,(col,value) in zip(range(2020,2025),occupied[1:]):
        if not isinstance(value,(int,float)): continue
        claim(sid,'stat-hunting-'+sid+'-'+str(year),'stat-environment-2025',value=int(value),territory='Отчитавшиеся охотничьи хозяйства Кыргызстана; переменный охват',page=f'таблица 4.19, {sheet}!{s.cell(row,col).coordinate}',summary='Ведомственный годовой показатель: '+label+'.',statisticalReferenceYear=year,sourceLabel=label,methodology='Свод данных Минприроды; полевые даты, повторный учёт и обнаруживаемость не раскрыты.',limitations=['Годовой отчётный показатель не подставлен вместо точной даты полевых работ.','57/65/64/63/43 отчитавшихся хозяйства по годам; сравниваемая площадь меняется.','Русское видовое название без taxon ID; для марала и туркестанской рыси нужен контроль соответствия современной концепции.'])
w.close()
